// CPython `repr()` / `str()` string-formatting reproduced in pure JavaScript.
//
// Data model convention (shared across this project):
//   dict -> Map, str -> string, int -> BigInt, float -> number,
//   bool -> boolean, None -> null, list -> Array.
//
// No external dependencies. ESM only.

// ---------------------------------------------------------------------------
// str.isprintable()
// ---------------------------------------------------------------------------

// CPython's Py_UNICODE_ISPRINTABLE(): a character is *not* printable when its
// Unicode general category is one of Cc, Cf, Cs, Co, Cn, Zl, Zp, Zs.  The
// single exception is U+0020 SPACE, which Python treats as printable.
// Built once, at module scope.
const NONPRINTABLE_RE =
  /[\p{Cc}\p{Cf}\p{Cs}\p{Co}\p{Cn}\p{Zl}\p{Zp}\p{Zs}]/u;

/**
 * Returns true if every code point of `str` is printable in CPython's sense.
 * The empty string is printable (matching `''.isprintable() == True`).
 *
 * @param {string} str
 * @returns {boolean}
 */
export function isPrintable(str) {
  const s = String(str);
  for (const ch of s) {
    // U+0020 is the one member of Zs that Python considers printable.
    if (ch === ' ') continue;
    if (NONPRINTABLE_RE.test(ch)) return false;
  }
  return true;
}

/**
 * Single-code-point variant of isPrintable(); `ch` must be one code point.
 *
 * @param {string} ch
 * @returns {boolean}
 */
function isPrintableChar(ch) {
  if (ch === ' ') return true;
  return !NONPRINTABLE_RE.test(ch);
}

function hex(n, width) {
  return n.toString(16).padStart(width, '0');
}

// ---------------------------------------------------------------------------
// repr(str)
// ---------------------------------------------------------------------------

/**
 * CPython `repr()` of a `str`.
 *
 * Quote selection: `'` normally; `"` when the string contains `'` but no `"`.
 * Escapes: `\\`, the active quote, `\t`, `\n`, `\r`; every other
 * non-printable code point becomes `\xhh`, `\uhhhh` or `\Uhhhhhhhh`.
 * Printable code points (letters, CJK, emoji, combining marks, ...) are raw.
 *
 * @param {string} s
 * @returns {string}
 */
export function pyStrRepr(s) {
  const str = String(s);

  let quote = "'";
  if (str.includes("'") && !str.includes('"')) quote = '"';

  let out = quote;
  for (const ch of str) {
    if (ch === quote || ch === '\\') {
      out += '\\' + ch;
      continue;
    }
    if (ch === '\t') {
      out += '\\t';
      continue;
    }
    if (ch === '\n') {
      out += '\\n';
      continue;
    }
    if (ch === '\r') {
      out += '\\r';
      continue;
    }
    if (isPrintableChar(ch)) {
      out += ch;
      continue;
    }
    const cp = ch.codePointAt(0);
    if (cp <= 0xff) out += '\\x' + hex(cp, 2);
    else if (cp <= 0xffff) out += '\\u' + hex(cp, 4);
    else out += '\\U' + hex(cp, 8);
  }
  return out + quote;
}

// ---------------------------------------------------------------------------
// repr(float)
// ---------------------------------------------------------------------------

// `Number.prototype.toExponential()` called with no argument is specified to
// use "as many digits as necessary to uniquely specify the number", i.e. the
// same shortest-round-trip digit string CPython's repr() produces.
const EXP_RE = /^(-?)(\d)(?:\.(\d+))?e([+-]\d+)$/;

/**
 * CPython `repr()` of a `float`.
 *
 * Shortest round-tripping digits, always with a fractional part in fixed
 * notation (`1.0`), exponential notation when the decimal point position is
 * <= -4 or > 16 (so 1e15 -> '1000000000000000.0' but 1e16 -> '1e+16', and
 * 0.0001 -> '0.0001' but 0.00001 -> '1e-05').  Exponents always carry a sign
 * and at least two digits.  Non-finite values are 'inf' / '-inf' / 'nan'.
 *
 * @param {number|bigint} value
 * @returns {string}
 */
export function pyFloatRepr(value) {
  const n = typeof value === 'bigint' ? Number(value) : Number(value);

  if (Number.isNaN(n)) return 'nan';
  if (n === Infinity) return 'inf';
  if (n === -Infinity) return '-inf';

  const neg = n < 0 || Object.is(n, -0);
  const abs = neg ? -n : n;

  if (abs === 0) return neg ? '-0.0' : '0.0';

  const m = EXP_RE.exec(abs.toExponential());
  if (m === null) {
    // Should be unreachable; fall back to a plain conversion.
    return (neg ? '-' : '') + String(abs);
  }
  const lead = m[2];
  const rest = m[3] || '';
  const digits = lead + rest;
  const exp10 = Number.parseInt(m[4], 10);
  // decpt: position of the decimal point relative to `digits`
  // (value === 0.DIGITS * 10**decpt).
  const decpt = exp10 + 1;

  let out;
  if (decpt <= -4 || decpt > 16) {
    const sign = exp10 < 0 ? '-' : '+';
    out =
      lead +
      (rest ? '.' + rest : '') +
      'e' +
      sign +
      String(Math.abs(exp10)).padStart(2, '0');
  } else if (decpt <= 0) {
    out = '0.' + '0'.repeat(-decpt) + digits;
  } else if (decpt >= digits.length) {
    out = digits + '0'.repeat(decpt - digits.length) + '.0';
  } else {
    out = digits.slice(0, decpt) + '.' + digits.slice(decpt);
  }
  return neg ? '-' + out : out;
}

// ---------------------------------------------------------------------------
// repr(int)
// ---------------------------------------------------------------------------

/**
 * CPython `repr()` of an `int` (represented as a BigInt in this project).
 *
 * @param {bigint|number} value
 * @returns {string}
 */
export function pyIntRepr(value) {
  if (typeof value === 'bigint') return value.toString(10);
  const n = Number(value);
  if (!Number.isFinite(n)) return pyFloatRepr(n);
  if (Number.isInteger(n)) return BigInt(n).toString(10);
  return Math.trunc(n).toString(10);
}

// ---------------------------------------------------------------------------
// repr(object) dispatch
// ---------------------------------------------------------------------------

/**
 * CPython `repr()` for the project's data model.
 *
 * @param {*} value
 * @returns {string}
 */
export function pyRepr(value) {
  if (value === null || value === undefined) return 'None';

  switch (typeof value) {
    case 'string':
      return pyStrRepr(value);
    case 'bigint':
      return pyIntRepr(value);
    case 'number':
      return pyFloatRepr(value);
    case 'boolean':
      return value ? 'True' : 'False';
    default:
      break;
  }

  if (Array.isArray(value)) {
    let parts = '';
    for (let i = 0; i < value.length; i++) {
      if (i > 0) parts += ', ';
      parts += pyRepr(value[i]);
    }
    return '[' + parts + ']';
  }

  if (value instanceof Map) {
    if (value.size === 0) return '{}';
    let parts = '';
    let first = true;
    for (const [k, v] of value) {
      if (!first) parts += ', ';
      first = false;
      parts += pyRepr(k) + ': ' + pyRepr(v);
    }
    return '{' + parts + '}';
  }

  if (typeof value === 'object') {
    const keys = Object.keys(value);
    if (keys.length === 0) return '{}';
    let parts = '';
    for (let i = 0; i < keys.length; i++) {
      if (i > 0) parts += ', ';
      parts += pyRepr(keys[i]) + ': ' + pyRepr(value[keys[i]]);
    }
    return '{' + parts + '}';
  }

  return String(value);
}

/**
 * CPython `str()`: strings are returned unchanged, everything else uses repr().
 *
 * @param {*} value
 * @returns {string}
 */
export function pyStr(value) {
  if (typeof value === 'string') return value;
  return pyRepr(value);
}

// CPython `json` module (dumps/loads) reproduced in pure JavaScript.
//
// Data model convention (shared across this project):
//   dict -> Map, str -> string, int -> BigInt, float -> number,
//   bool -> boolean, None -> null, list -> Array.
//
// Float formatting is delegated to pyFloatRepr() so the `repr()` logic lives
// in exactly one place.

import { pyFloatRepr } from './pyrepr.mjs';

// ---------------------------------------------------------------------------
// dumps
// ---------------------------------------------------------------------------

// The short escapes used by CPython's C encoder.  Note that `/` is NOT escaped.
const SHORT_ESCAPES = new Map([
  ['"', '\\"'],
  ['\\', '\\\\'],
  ['\b', '\\b'],
  ['\t', '\\t'],
  ['\n', '\\n'],
  ['\f', '\\f'],
  ['\r', '\\r'],
]);

function u4(code) {
  return '\\u' + code.toString(16).padStart(4, '0');
}

/**
 * JSON string literal, byte-identical to CPython's C encoder.
 *
 * Iterates UTF-16 code units, so with ensureAscii an astral character becomes
 * a surrogate pair of two `\uxxxx` escapes (exactly what CPython emits).
 *
 * @param {string} s
 * @param {boolean} ensureAscii
 * @returns {string}
 */
export function pyJsonEncodeString(s, ensureAscii = true) {
  const str = String(s);
  let out = '"';
  for (let i = 0; i < str.length; i++) {
    const ch = str[i];
    const short = SHORT_ESCAPES.get(ch);
    if (short !== undefined) {
      out += short;
      continue;
    }
    const code = str.charCodeAt(i);
    if (code < 0x20) {
      out += u4(code);
    } else if (code > 0x7e && ensureAscii) {
      out += u4(code);
    } else {
      out += ch;
    }
  }
  return out + '"';
}

function jsonFloat(n) {
  if (Number.isNaN(n)) return 'NaN';
  if (n === Infinity) return 'Infinity';
  if (n === -Infinity) return '-Infinity';
  return pyFloatRepr(n);
}

function keyToString(key) {
  if (typeof key === 'string') return key;
  if (typeof key === 'bigint') return key.toString(10);
  if (typeof key === 'boolean') return key ? 'true' : 'false';
  if (key === null || key === undefined) return 'null';
  if (typeof key === 'number') return jsonFloat(key);
  throw new TypeError('keys must be str, int, float, bool or None');
}

function entriesOf(value) {
  if (value instanceof Map) return [...value.entries()];
  return Object.keys(value).map((k) => [k, value[k]]);
}

/**
 * CPython `json.dumps()`.
 *
 * @param {*} value
 * @param {{ensureAscii?: boolean, separators?: [string,string]|null,
 *          sortKeys?: boolean, indent?: number|bigint|string|null}} [options]
 * @returns {string}
 */
export function pyJsonDumps(value, options = {}) {
  const {
    ensureAscii = true,
    separators = null,
    sortKeys = false,
    indent = null,
  } = options || {};

  let indentStr = null;
  if (indent !== null && indent !== undefined) {
    indentStr =
      typeof indent === 'string' ? indent : ' '.repeat(Number(indent));
  }

  // CPython: default separators are (', ', ': '); when indent is given and no
  // separators are supplied, the item separator loses its trailing space.
  let itemSep = ', ';
  let keySep = ': ';
  if (separators !== null && separators !== undefined) {
    itemSep = separators[0];
    keySep = separators[1];
  } else if (indentStr !== null) {
    itemSep = ',';
  }

  const seen = new Set();

  function encode(v, level) {
    if (v === null || v === undefined) return 'null';

    switch (typeof v) {
      case 'string':
        return pyJsonEncodeString(v, ensureAscii);
      case 'bigint':
        return v.toString(10);
      case 'number':
        return jsonFloat(v);
      case 'boolean':
        return v ? 'true' : 'false';
      default:
        break;
    }

    if (typeof v !== 'object') {
      throw new TypeError(
        'Object of type ' + typeof v + ' is not JSON serializable',
      );
    }

    if (seen.has(v)) throw new TypeError('Circular reference detected');
    seen.add(v);
    try {
      let newline = '';
      let closeNewline = '';
      if (indentStr !== null) {
        newline = '\n' + indentStr.repeat(level + 1);
        closeNewline = '\n' + indentStr.repeat(level);
      }

      if (Array.isArray(v)) {
        if (v.length === 0) return '[]';
        const parts = v.map((item) => encode(item, level + 1));
        return '[' + newline + parts.join(itemSep + newline) + closeNewline + ']';
      }

      const entries = entriesOf(v).map(([k, val]) => [keyToString(k), val]);
      if (entries.length === 0) return '{}';
      if (sortKeys) {
        // UTF-16 code-unit order, i.e. plain JS `<` on strings.
        entries.sort((a, b) => (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0));
      }
      const parts = entries.map(
        ([k, val]) =>
          pyJsonEncodeString(k, ensureAscii) + keySep + encode(val, level + 1),
      );
      return '{' + newline + parts.join(itemSep + newline) + closeNewline + '}';
    } finally {
      seen.delete(v);
    }
  }

  return encode(value, 0);
}

// ---------------------------------------------------------------------------
// loads -- hand-rolled recursive-descent parser
// ---------------------------------------------------------------------------

const WS = new Set([' ', '\t', '\n', '\r']);

const STRING_ESCAPES = new Map([
  ['"', '"'],
  ['\\', '\\'],
  ['/', '/'],
  ['b', '\b'],
  ['f', '\f'],
  ['n', '\n'],
  ['r', '\r'],
  ['t', '\t'],
]);

class JsonParser {
  constructor(text) {
    this.s = text;
    this.i = 0;
  }

  fail(msg) {
    throw new Error(msg + ': line 1 column ' + (this.i + 1) + ' (char ' + this.i + ')');
  }

  skipWs() {
    while (this.i < this.s.length && WS.has(this.s[this.i])) this.i++;
  }

  peek() {
    return this.i < this.s.length ? this.s[this.i] : '';
  }

  expect(ch) {
    if (this.s[this.i] !== ch) this.fail("Expecting '" + ch + "' delimiter");
    this.i++;
  }

  literal(word) {
    if (this.s.startsWith(word, this.i)) {
      this.i += word.length;
      return true;
    }
    return false;
  }

  parseValue() {
    this.skipWs();
    if (this.i >= this.s.length) this.fail('Expecting value');
    const ch = this.s[this.i];
    switch (ch) {
      case '{':
        return this.parseObject();
      case '[':
        return this.parseArray();
      case '"':
        return this.parseString();
      default:
        break;
    }
    if (this.literal('true')) return true;
    if (this.literal('false')) return false;
    if (this.literal('null')) return null;
    // CPython's json accepts these non-standard constants by default.
    if (this.literal('NaN')) return NaN;
    if (this.literal('Infinity')) return Infinity;
    if (this.literal('-Infinity')) return -Infinity;
    if (ch === '-' || (ch >= '0' && ch <= '9')) return this.parseNumber();
    this.fail('Expecting value');
    return undefined;
  }

  parseObject() {
    this.expect('{');
    const map = new Map();
    this.skipWs();
    if (this.peek() === '}') {
      this.i++;
      return map;
    }
    for (;;) {
      this.skipWs();
      if (this.peek() !== '"') this.fail('Expecting property name enclosed in double quotes');
      const key = this.parseString();
      this.skipWs();
      this.expect(':');
      const value = this.parseValue();
      // Document order is preserved; a repeated key keeps its first position
      // (Map.set semantics) with the last value, exactly like CPython's dict.
      map.set(key, value);
      this.skipWs();
      const ch = this.peek();
      if (ch === ',') {
        this.i++;
        continue;
      }
      if (ch === '}') {
        this.i++;
        return map;
      }
      this.fail("Expecting ',' delimiter");
    }
  }

  parseArray() {
    this.expect('[');
    const arr = [];
    this.skipWs();
    if (this.peek() === ']') {
      this.i++;
      return arr;
    }
    for (;;) {
      arr.push(this.parseValue());
      this.skipWs();
      const ch = this.peek();
      if (ch === ',') {
        this.i++;
        continue;
      }
      if (ch === ']') {
        this.i++;
        return arr;
      }
      this.fail("Expecting ',' delimiter");
    }
  }

  hex4() {
    const h = this.s.slice(this.i, this.i + 4);
    if (h.length !== 4 || !/^[0-9a-fA-F]{4}$/.test(h)) {
      this.fail('Invalid \\uXXXX escape');
    }
    this.i += 4;
    return Number.parseInt(h, 16);
  }

  parseString() {
    this.expect('"');
    let out = '';
    for (;;) {
      if (this.i >= this.s.length) this.fail('Unterminated string starting at');
      const ch = this.s[this.i];
      if (ch === '"') {
        this.i++;
        return out;
      }
      if (ch === '\\') {
        this.i++;
        if (this.i >= this.s.length) this.fail('Unterminated string starting at');
        const esc = this.s[this.i];
        if (esc === 'u') {
          this.i++;
          const unit = this.hex4();
          if (unit >= 0xd800 && unit <= 0xdbff && this.s.startsWith('\\u', this.i)) {
            const save = this.i;
            this.i += 2;
            const low = this.hex4();
            if (low >= 0xdc00 && low <= 0xdfff) {
              out += String.fromCodePoint(
                0x10000 + ((unit - 0xd800) << 10) + (low - 0xdc00),
              );
              continue;
            }
            this.i = save;
          }
          out += String.fromCharCode(unit);
          continue;
        }
        const mapped = STRING_ESCAPES.get(esc);
        if (mapped === undefined) this.fail('Invalid \\escape');
        out += mapped;
        this.i++;
        continue;
      }
      if (ch < ' ') this.fail('Invalid control character at');
      out += ch;
      this.i++;
    }
  }

  parseNumber() {
    const start = this.i;
    if (this.peek() === '-') this.i++;
    if (this.peek() === '0') {
      this.i++;
    } else if (this.peek() >= '1' && this.peek() <= '9') {
      while (this.peek() >= '0' && this.peek() <= '9') this.i++;
    } else {
      this.fail('Expecting value');
    }
    let isFloat = false;
    if (this.peek() === '.') {
      isFloat = true;
      this.i++;
      if (!(this.peek() >= '0' && this.peek() <= '9')) this.fail('Expecting value');
      while (this.peek() >= '0' && this.peek() <= '9') this.i++;
    }
    const e = this.peek();
    if (e === 'e' || e === 'E') {
      isFloat = true;
      this.i++;
      if (this.peek() === '+' || this.peek() === '-') this.i++;
      if (!(this.peek() >= '0' && this.peek() <= '9')) this.fail('Expecting value');
      while (this.peek() >= '0' && this.peek() <= '9') this.i++;
    }
    const raw = this.s.slice(start, this.i);
    // Integral literals (no '.', 'e' or 'E') become Python ints -> BigInt.
    return isFloat ? Number(raw) : BigInt(raw);
  }
}

/**
 * CPython `json.loads()` for the project's data model.
 *
 * Objects become Maps in document order, arrays become Arrays, integer
 * literals become BigInt, other numbers become JS numbers.  Throws on
 * malformed input.
 *
 * @param {string} text
 * @returns {*}
 */
export function pyJsonLoads(text) {
  if (typeof text !== 'string') {
    throw new TypeError('the JSON object must be str');
  }
  const p = new JsonParser(text);
  const value = p.parseValue();
  p.skipWs();
  if (p.i !== text.length) p.fail('Extra data');
  return value;
}

// CPython `print()` reproduced in pure JavaScript.

import { pyStr } from './pyrepr.mjs';

/**
 * CPython `print(*values)`: joins str(v) with a single space and writes the
 * result plus a trailing newline to stdout, byte-for-byte like Python.
 *
 * @param {...*} values
 * @returns {void}
 */
export function pyPrint(...values) {
  let out = '';
  for (let i = 0; i < values.length; i++) {
    if (i > 0) out += ' ';
    out += pyStr(values[i]);
  }
  process.stdout.write(out + '\n');
}

// Differential test: our JS modules vs the reference CPython binary.
import { execFileSync } from 'node:child_process';
import { pyRepr } from '/output/lib/py/pyrepr.mjs';
import { pyJsonDumps } from '/output/lib/py/pyjson.mjs';

const EXE = '/workspace/dataset/test10_executable';

const cases = [
  ['single quote', "it's"],
  ['both quote kinds', `mix 'sq' and "dq"`],
  ['double quotes only', '"dq only" here'],
  ['backslashes', 'a\\b\\\\c path\\to\\file'],
  ['newline', 'line1\nline2'],
  ['tab', 'tab\there'],
  ['carriage return', 'car\rriage'],
  ['ctrl DEL ESC', '\x01\x7f\x1b'],
  ['bell + vtab + formfeed', '\x07\x0b\x0c'],
  ['soft hyphen/ZWSP/combining acute', '­​́'],
  ['CJK', '中文测试'],
  ['emoji astral', '\u{1F600}ok'],
  ['astral + noncharacter', '\u{1F600}\u{10FFFF}'],
  ['script tag', '</script>'],
  ['forward slash', 'a/b'],
  ['empty string', ''],
  ['line/para separators', 'x y z'],
  ['NBSP + spaces', 'space   and nbsp'],
  ['accents', 'Ünïcodé'],
  ['LRM format char', 'left‎right'],
  ['everything', `tab\ttab'quote"both\\end\né\u{1F4A9}\x00x`.replace('\x00', '')],
  ['json-ish', '{"key": "val1"}'],
  ['private use + unassigned', '͸'],
  ['only DEL', '\x7f'],
  ['quote at edges', `'"'`],
];

function b64urlDecode(seg) {
  return Buffer.from(seg, 'base64url').toString('utf8');
}

const rows = [];
let allPass = true;

for (const [name, s] of cases) {
  // Use the string as BOTH subject and user_data (data gets a variant) so each
  // run exercises the value twice.
  const subject = s;
  const userData = s === '' ? '' : s + '|' + s;
  let out;
  try {
    out = execFileSync(EXE, ['--subject', subject, '--user_data', userData], {
      encoding: 'utf8',
    });
  } catch (e) {
    rows.push([name, 'EXEC-FAIL', 'EXEC-FAIL', String(e.message).slice(0, 80)]);
    allPass = false;
    continue;
  }
  const lines = out.split('\n');
  const token = lines[0];
  const expectedRepr = lines[1];
  const expectedJson = b64urlDecode(token.split('.')[1]);

  const payload = new Map([
    ['sub', subject],
    ['data', userData],
  ]);
  const gotRepr = pyRepr(payload);
  const gotJson = pyJsonDumps(payload, { separators: [',', ':'] });

  const reprOk = gotRepr === expectedRepr;
  const jsonOk = gotJson === expectedJson;
  if (!reprOk || !jsonOk) allPass = false;
  rows.push([
    name,
    reprOk ? 'PASS' : 'FAIL',
    jsonOk ? 'PASS' : 'FAIL',
    reprOk && jsonOk
      ? ''
      : `\n    exp repr: ${JSON.stringify(expectedRepr)}\n    got repr: ${JSON.stringify(gotRepr)}\n    exp json: ${JSON.stringify(expectedJson)}\n    got json: ${JSON.stringify(gotJson)}`,
  ]);
}

